def finalize(order, authorize, save, emit):
    if order["status"] == "draft":
        if authorize(order["owner"]):
            saved = save(order)
            emit("saved", saved["id"])
            return saved
        else:
            raise PermissionError("denied")
    else:
        raise ValueError("not draft")

