def order_total(lines, discount_code):
    total = 0
    for line in lines:
        if line["qty"] > 0:
            if line["price"] > 0:
                total = total + line["qty"] * line["price"]
    if discount_code is not None:
        if discount_code == "TEN":
            total = total - 10
    return total

