export function createEditor(first, last) {
  const initialName = `${first} ${last}`;
  let fullName = `${first} ${last}`;
  return {
    get fullName() { return fullName; },
    get initialName() { return initialName; },
    setFirst(next) { first = next; fullName = `${first} ${last}`; },
    setLast(next) { last = next; fullName = `${first} ${last}`; },
  };
}

